type BackoffConfig struct {
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each failed retry.
	Multiplier float64
	// Jitter is the randomization factor applied to backoff delays.
	Jitter float64
}

type Exponential struct {
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
	// BaseDelay is the amount of time to wait before retrying after the first failure.
	BaseDelay time.Duration
	// Multiplier is the factor applied to the backoff after each failed retry.
	Multiplier float64
	// Jitter is the randomization factor applied to backoff delays.
	Jitter float64
}

func (bc Exponential) Backoff(retries int) time.Duration {
	baseDelay := bc.BaseDelay
	if baseDelay <= 0 {
		baseDelay = time.Second
	}
	maxDelay := bc.MaxDelay
	if maxDelay <= 0 {
		maxDelay = 120 * time.Second
	}
	multiplier := bc.Multiplier
	if multiplier <= 0 {
		multiplier = 1.6
	}
	jitter := bc.Jitter
	if jitter < 0 {
		jitter = 0
	}

	backoff := float64(baseDelay)
	for backoff < float64(maxDelay) && retries > 0 {
		backoff *= multiplier
		retries--
	}
	if backoff > float64(maxDelay) {
		backoff = float64(maxDelay)
	}
	// Randomize backoff delays so that if a cluster of requests start at
	// the same time, they won't operate in lockstep.
	backoff *= 1 + jitter*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

var DefaultBackoffConfig = BackoffConfig{
	MaxDelay:   120 * time.Second,
	BaseDelay:  time.Second,
	Multiplier: 1.6,
	Jitter:     0.2,
}

func WithBackoffConfig(b BackoffConfig) DialOption {
	return withBackoff(backoff.Exponential{
		MaxDelay:   b.MaxDelay,
		BaseDelay:  b.BaseDelay,
		Multiplier: b.Multiplier,
		Jitter:     b.Jitter,
	})
}

const (
	// baseDelay is the amount of time to wait before retrying after the first
	// failure.
	baseDelay = 1.0 * time.Second
	// factor is applied to the backoff after each retry.
	factor = 1.6
	// jitter provides a range to randomize backoff delays.
	jitter = 0.2
)

expectedValue := backoff.Exponential{
		MaxDelay:   expected.MaxDelay,
		BaseDelay:  expected.BaseDelay,
		Multiplier: expected.Multiplier,
		Jitter:     expected.Jitter,
	}

